package com.markethub.vendor.admin.api;
import com.markethub.identity.domain.AppUser; import com.markethub.identity.domain.UserRole; import com.markethub.identity.repository.AppUserRepository; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.List; import java.util.UUID;
@Service public class AdminVendorService {
 private final JdbcTemplate jdbc; private final AppUserRepository users; public AdminVendorService(JdbcTemplate jdbc,AppUserRepository users){this.jdbc=jdbc;this.users=users;}
 public record ApplicationView(UUID vendorId,UUID ownerUserId,String displayName,String status,Instant createdAt,String rejectionReason){}
 public List<ApplicationView> pending(){return jdbc.query("select id,owner_user_id,display_name,status,created_at,rejection_reason from vendors where status='PENDING' order by created_at",(rs,n)->view(rs.getObject("id",UUID.class),rs.getObject("owner_user_id",UUID.class),rs.getString("display_name"),rs.getString("status"),rs.getTimestamp("created_at").toInstant(),rs.getString("rejection_reason")));}
 @Transactional public ApplicationView approve(UUID vendorId,UUID actorId){ApplicationView app=requirePending(vendorId);AppUser owner=users.findById(app.ownerUserId()).orElseThrow(()->new IllegalStateException("Vendor owner account was not found"));if(owner.getRole()!=UserRole.CUSTOMER&&owner.getRole()!=UserRole.VENDOR)throw new IllegalStateException("Owner account is not eligible for vendor approval");owner.activateVendorRole();users.save(owner);int changed=jdbc.update("update vendors set status='APPROVED',reviewed_at=now(),reviewed_by=?,rejection_reason=null where id=? and status='PENDING'",actorId,vendorId);if(changed!=1)throw new IllegalStateException("Vendor application was concurrently reviewed");return find(vendorId);}
 @Transactional public ApplicationView reject(UUID vendorId,UUID actorId,String reason){requirePending(vendorId);int changed=jdbc.update("update vendors set status='REJECTED',reviewed_at=now(),reviewed_by=?,rejection_reason=? where id=? and status='PENDING'",actorId,reason.trim(),vendorId);if(changed!=1)throw new IllegalStateException("Vendor application was concurrently reviewed");return find(vendorId);}
 private ApplicationView requirePending(UUID id){ApplicationView a=find(id);if(!"PENDING".equals(a.status()))throw new IllegalStateException("Only pending applications can be reviewed");return a;}
 private ApplicationView find(UUID id){return jdbc.query("select id,owner_user_id,display_name,status,created_at,rejection_reason from vendors where id=?",(rs,n)->view(rs.getObject("id",UUID.class),rs.getObject("owner_user_id",UUID.class),rs.getString("display_name"),rs.getString("status"),rs.getTimestamp("created_at").toInstant(),rs.getString("rejection_reason")),id).stream().findFirst().orElseThrow(()->new IllegalArgumentException("Vendor application not found"));}
 private ApplicationView view(UUID id,UUID owner,String name,String status,Instant created,String reason){return new ApplicationView(id,owner,name,status,created,reason);}
}